-- Estimates retain the original campus nutrition panel and their own sources.
alter table public.food_versions
  add column estimated_nutrition jsonb
    check (jsonb_typeof(estimated_nutrition) = 'object');
alter table public.menu_components
  add column estimated_nutrition jsonb
    check (jsonb_typeof(estimated_nutrition) = 'object');

-- Pin a backfill to the audited publication so a changed recipe picks up new
-- campus facts without inheriting a reference for the prior version.
create table benson_private.food_nutrition_estimates (
  source_namespace text not null,
  source_item_id text not null,
  base_hash text not null,
  estimate jsonb not null check (jsonb_typeof(estimate) = 'object'),
  primary key (source_namespace, source_item_id, base_hash)
);
revoke all on benson_private.food_nutrition_estimates from public, anon, authenticated;

create function benson_private.catalog_version_with_estimate(p_id uuid)
returns uuid language plpgsql set search_path=pg_catalog,benson_private as $$
declare
  base public.food_versions%rowtype;
  enriched public.food_versions%rowtype;
  payload jsonb;
  facts jsonb;
  version uuid;
begin
  select * into strict base from public.food_versions where id=p_id;
  select e.estimate into payload
    from benson_private.food_nutrition_estimates e
    join public.food_items i on i.source_namespace=e.source_namespace and i.source_item_id=e.source_item_id
    where i.id=base.food_item_id and e.base_hash=base.content_hash;

  if payload is null then return p_id; end if;
  facts:=payload->'nutrients';
  enriched:=base;
  enriched.id:=gen_random_uuid();
  enriched.content_hash:='catalog-estimate:'||base.content_hash||':'||md5(payload::text);
  enriched.captured_at:=greatest(clock_timestamp(),base.captured_at+interval '1 microsecond');
  enriched.nutrition_source:='estimated';
  enriched.estimated_nutrition:=payload;
  enriched.serving_description:=coalesce(base.serving_description,payload->>'serving');
  enriched.serving_weight_g:=coalesce(base.serving_weight_g,(payload->>'grams')::numeric);
  enriched.calories_kcal:=coalesce(base.calories_kcal,amount(facts,'calories',''));
  enriched.protein_g:=coalesce(base.protein_g,amount(facts,'proteinContent','g'));
  enriched.carbohydrate_g:=coalesce(base.carbohydrate_g,amount(facts,'carbohydrateContent','g'));
  enriched.total_fat_g:=coalesce(base.total_fat_g,amount(facts,'fatContent','g'));
  enriched.saturated_fat_g:=coalesce(base.saturated_fat_g,amount(facts,'saturatedFatContent','g'));
  enriched.trans_fat_g:=coalesce(base.trans_fat_g,amount(facts,'transFatContent','g'));
  enriched.fiber_g:=coalesce(base.fiber_g,amount(facts,'fiberContent','g'));
  enriched.sugar_g:=coalesce(base.sugar_g,amount(facts,'sugarContent','g'));
  enriched.sodium_mg:=coalesce(base.sodium_mg,amount(facts,'sodiumContent','mg'));
  enriched.cholesterol_mg:=coalesce(base.cholesterol_mg,amount(facts,'cholesterolContent','mg'));

  insert into public.food_versions select enriched.*
    on conflict (food_item_id,content_hash) do nothing returning id into version;
  if version is null then
    select id into strict version from public.food_versions
      where food_item_id=enriched.food_item_id and content_hash=enriched.content_hash;
  end if;

  insert into public.food_version_components (
    food_version_id, position, option_position, component_id, display_label, choice_group
  )
  select version, position, option_position, component_id, display_label, choice_group
    from public.food_version_components where food_version_id=p_id
    on conflict do nothing;

  insert into public.food_version_recipe_components (
    food_version_id, position, source_recipe_id, name, source_group, nutrition_status, serving_evidence
  )
  select version, position, source_recipe_id, name, source_group, nutrition_status, serving_evidence
    from public.food_version_recipe_components where food_version_id=p_id
    on conflict do nothing;

  return version;
end $$;
revoke all on function benson_private.catalog_version_with_estimate(uuid) from public, anon, authenticated;

alter function benson_private.catalog_food(jsonb,text,timestamptz) rename to catalog_food_publication;
create function benson_private.catalog_food(item jsonb, url text, captured timestamptz)
returns uuid language sql set search_path=pg_catalog,benson_private as $$
  select catalog_version_with_estimate(catalog_food_publication(item,url,captured))
$$;
revoke all on function benson_private.catalog_food(jsonb,text,timestamptz) from public, anon, authenticated;


